eiding tot vragen over identiteit en over gedrag dat vanzelfsprekend lijkt. De stukken staan los van elkaar en behouden de directe blik van de krantencolumn. Samen vormen ze een reeks observaties over het leven van een jonge volwassene en de wereld om haar heen.","work_id":987160005,"evidence":[{"note":"Distinct2011firstcolumncollection, selectedDutchPaperbackthirdprinting2012 ISBN9789020412345. PublisherBureauISBN confirmsfirst2011printededitionand2012ebookseparately, exactprintretained. SameISBNprimarycreditHannaBervoets andKBHannaMarleenBervoets1984 plusauthorCV establishprimaryrole, no author merge.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p334622476"],"reference":"new-work-dossier-readings-061.json#223","checked_at":"2026-11-03T12:14:47.005Z"},{"type":"original_substantive_source_review","review":"content-amendment-026.json","sources":["https://metadata.isbn.nl/127424/leuk-zeg-doei.html","https://www.hannabervoets.com/gallery/HannaBervoetsEnglish2022.pdf","https://www.hpdetijd.nl/nieuws/leven/21445/hanna-bervoets","https://data.bibliotheken.nl/id/nbt/p334622476"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"ad7728ad84d6565b5adcb50bed40aa3ef1369b073b7fc288ee79f30a33f5d5dc","cover_id":12345993,"asset_url":null,"reference":"cover-semantic-review-061.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/127424/leuk-zeg-doei.html","reviewed_at":"2026-11-03T12:14:47.005+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-061","review_status":"approved","bound_author_id":969300004}'::jsonb as exact union all select 'catalog_